public static void main(Args _args)
{
    if (_args == null 
        || _args.record() == null
        || _args.record().TableId != tableNum(ISMBatchableTelemetryParameterSetup))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    ISMBatchableTelemetryParameterSetup batchableTelemetryParameterSetup = 
        _args.record() as ISMBatchableTelemetryParameterSetup;

    ISMBatchableTelemetryStatusTable statusTable;
    select firstonly1 statusTable
        where statusTable.ParameterSetup == batchableTelemetryParameterSetup.RecId
            && statusTable.Batch != 0;
    Batch batch;
    BatchJob batchJob;
    ttsbegin;
    select firstonly1 forupdate batchJob
        exists join batch 
            where batch.RecId == statusTable.Batch
                && batch.BatchJobId == batchJob.RecId;
    if (batchJob.RecId == 0)
    {
        warning("There exists no batch job to stop.");
        return;
    }
    if (batchJob.Status == BatchStatus::Finished
        || batchJob.Status == BatchStatus::Canceled
        || batchJob.Status == BatchStatus::Error
        || batchJob.Status == BatchStatus::Hold)
    {
        warning("The batch job is already stopped.");
        return;
    }

    if (batchJob.Status == BatchStatus::Executing)
    {
        // Update the status to canceled
        batchJob.Status = BatchStatus::Cancelling;
        if (batchJob.validateWrite())
        {
            batchJob.update();
            info(strFmt("Batch job %1 was stopped", batchJob.RecId));
        }
    }
    else
    {
        info(strFmt("Batch job %1 in state %2 cannot be stopped", batch.RecId, batchJob.Status));
    }
    ttscommit;
}
